head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vLstTrdWeekStart = "";
scwin.vLstTrdWeekEnd = "";
scwin.vLstTrdWeekFm = "";
scwin.vLstTrdDd = "";
scwin.vLstTrdDdFm = "";
scwin.vFromCd = "";
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용
scwin.getPar, scwin.setPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        $c.cm.PanelToGroupBox(panel_Item);
        cmb_DISTR_CD.setValue(1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05933.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name cmb_DISTR_CD_onselchange
 * @description cmb_DISTR_CD onselchange 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cmb_DISTR_CD_onselchange = async function() {
    try {
        await scwin.readSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05933.cmb_DISTR_CD_onselchange" });
    }
};

/**
 * @method
 * @name btn_Dscl_onclick
 * @description 「공시검토전송」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Dscl_onclick = async function() {
    try {
        await scwin.dscl();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05933.btn_Dscl_onclick" });
    }
};

/**
 * @method
 * @name btn_Print_onclick
 * @description 「인쇄」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Print_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF05933.xml", SCREN_PROCS_TP_CD_05);
        if (!scwin.checkForm()) return;
        scwin.print();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05933.btn_Print_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05933.btn_Close_onclick" });
    }
};

/**
