/**
 * @method
 * @name dts_Discls_OnLoadCompleted
 * @description dts_Discls 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Discls_OnLoadCompleted = function(rowcount) {

};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name getTrdReadSync
 * @description get Trd Read Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getTrdReadSync = async function() {
    const sbmOptions = {
        id : "sbm_dts_LstWeekTrd",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_LstWeekTrd=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    scwin.vLstTrdWeekStart = dts_LstWeekTrd.getCellData(1, "LST_TRD_WEEK_STRT");
    scwin.vLstTrdWeekEnd = dts_LstWeekTrd.getCellData(1, "LST_TRD_WEEK_END");
    scwin.vLstTrdWeekFm = scwin.dateForm(scwin.vLstTrdWeekStart) + "~" + scwin.dateForm2(scwin.vLstTrdWeekEnd);
    const sbmOptions2 = {
        id : "sbm_dts_LstTrd",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_LstTrd=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    scwin.vLstTrdDd = dts_LstTrd.getCellData(1, "LST_TRD_DD");
    scwin.vLstTrdDdFm = scwin.dateForm(scwin.vLstTrdDd);
};

/**
 * @method
 * @name readSync
 * @description read Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readSync = async function() {
    if (js_svrGubun === 'dr') {
        await $c.win.alert("DR에서 운영될때는 서비스가 제공되지 않습니다.");
        return;
    }
    const vDistrCd = cmb_DISTR_CD.getValue();
    await scwin.getTrdReadSync();
    url += "&SCREN_ID=" + "ULDSTF05933.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    let str = "";
    if (vDistrCd === '1') {
        scwin.vFromCd = '68960';
        // str = "내재변동성 변동비율 상위종목수 LP별 분포현황 공표";
        str = "LP별 내재변동성의 일관성 분포현황 공표"; // 20081023변경
        url += "&queryId=lds.stf.lstproc.select.elwimpvolt.daily.condition";
        url += "&{P}param01=" + scwin.vLstTrdDdFm;
        url += "&{P}param02=" + scwin.vLstTrdDd;
        url += "&{P}param03=" + scwin.vLstTrdDd;
    } else if (vDistrCd === '2') {
        scwin.vFromCd = '68958';
        // str = "발행시점대비 내재변동성 변동비율 상위종목수 LP별 분포현황 공표";
        str = "주간상장종목중 LP별 내재변동성의 일관성 분포현황 공표"; // 20081023변경

        url += "&queryId=lds.stf.lstproc.select.elwimpvolt.weekly.condition";
        url += "&{P}param01=" + scwin.vLstTrdWeekFm;
        url += "&{P}param02=" + scwin.vLstTrdWeekEnd;
        url += "&{P}param03=" + scwin.vLstTrdWeekEnd;
    }
    txb_INFO_TITLE.setValue(str);
    const sbmOptions = {
        id : "sbm_dts_Discls",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_Discls=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let vCtnt = "";
    for (let i = 1; i <= dts_Discls.getRowCount(); i++) {
        vCtnt += "\r\n";
        vCtnt += dts_Discls.getCellData(i, "TITLE");
    }
    txa_INFO_CONTN.text = vCtnt;
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name dateForm
 * @description date Form 처리
 * @param {String} pStr pStr
 * @returns {void}
 * @hidden N
 */
scwin.dateForm = function(pStr) {
    return "'" + pStr.substring(2, 4) + "." + pStr.substring(4, 6) + "." + pStr.substring(6, 8);
};

/**
 * @method
 * @name dateForm2
 * @description date Form2 처리
 * @param {String} pStr pStr
 * @returns {void}
 * @hidden N
 */
scwin.dateForm2 = function(pStr) {
    return pStr.substring(4, 6) + "." + pStr.substring(6, 8);
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {void}
 * @hidden N
 */
scwin.checkForm = function() {
    if (!$c.stf.checkEmptyValue(txb_INFO_TITLE, "제목")) return false;
    if (!$c.stf.checkMaxLength(txb_INFO_TITLE, 256, "제목")) return false;
    if (!$c.stf.checkEmptyValue(txa_INFO_CONTN, "내용")) return false;
    return true;
};

/**
 * @method
 * @name dscl
 * @description dscl 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dscl = async function() {
    if (!scwin.checkForm()) return;
    const vBzProcsNo = await $c.stf.getNewBzProcNo(dts_BzProcsNo);
    if (vBzProcsNo.length !== 14) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        return;
    }
    const OldGet = scwin.getPar;
    const OldSet = scwin.setPar;
    scwin.getPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
        arr[0] = scwin.vFromCd;
        arr[1] = vBzProcsNo; // 테스트할때는 첫번째 업무처리번호를 일단 넘긴다...
        arr[2] = '99999'; // 거래소코드
        arr[3] = '1';
        arr[4] = txa_INFO_CONTN.Text;
        arr[5] = '';

        // CopyDataSet( dts_Delistdetail , param_dts_isu) ;
        // CopyDataSet( dts_Isu , param_dts_mst) ;
        return arr.length;
    };
    scwin.setPar = function(arr) {

    };
    const wth = 730 + 5;
    const hgt = 785 + 30;
    const pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    const options = {
        id: "ULDSTF92024",
        title: "공시안내문작성",
        type: "browserPopup",
        width: wth,
        height: hgt,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/listingcommon/ULDSTF92024.gfm", options);
    scwin.getPar = OldGet;
    scwin.setPar = OldSet;
};

/**
 * @method
 * @name print
 * @description 화면을 인쇄한다.
 * @returns {void}
 * @hidden N
 */
scwin.print = function() {
    const sDepNm_1 = "";
    const sDepNm_2 = "";

    // PDF 리포트 파일명
    const pdf_rptname = "RLDSTF00004";
    let tInfoContn = txa_INFO_CONTN.text;
    if (tInfoContn !== '') {
        tInfoContn = $c.ut.replaceAll(tInfoContn, '\n', '<br>');
        tInfoContn = $c.ut.replaceAll(tInfoContn, ' ', '&nbsp;');
    } else {
        tInfoContn = $c.ut.defaultStrHtmlSpace(tInfoContn);
    }
    let userParam = [{
        uid: "DEP_NM_1",
        unm: $c.ut.defaultStrHtmlSpace(sDepNm_1)
    }, {
        uid: "DEP_NM_2",
        unm: $c.ut.defaultStrHtmlSpace(sDepNm_2)
    }, {
        uid: "ISUR_CD",
        unm: $c.ut.defaultStrHtmlSpace("")
    }, {
        uid: "COM_NM",
        unm: $c.ut.defaultStrHtmlSpace("")
    }, {
        uid: "TITLE",
        unm: txb_INFO_TITLE.getValue()
    }, {
        uid: "BODY",
        unm: tInfoContn
    }];

    // PDF Convert
    $c.rpt.fn_open_report_pdf(pdf_rptname, userParam);
};

/**
 * @method
 * @name printOld
 * @description 화면을 인쇄한다. (ASIS rexpert-bak 2018-04-03)
 * @returns {void}
 * @hidden N
 */
scwin.printOld = function() {

    // dts_Print.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
    // 껍데기만 만들고 사용자필드를 사용함
    dts_Print.insertRow();
    // dts_Print.NameValue(1, "TEST") = dtsObj.NameValue(1, "COM_NM");

    // 데이타셋
    // var testDateSet = rex_gfGetGauceCsvStrAll(dts_TempPrint, MxDataSet_emp_data );
    const testDateSet = rex_gfGetGauceCsvStr(dts_Print);
    // alert('[testDateSet]'+testDateSet);

    // Rexpert리포트 파일명
    // var rex_rptname = "test/sample4";
    const rex_rptname = "RLDSTF00004";
    let userParam = [{
        uid: "ISUR_CD",
        unm: ""
    }, {
        uid: "COM_NM",
        unm: ""
    }, {
        uid: "TITLE",
        unm: txb_INFO_TITLE.getValue()
    }, {
        uid: "BODY",
        unm: txa_INFO_CONTN.text
    }];

    // Rexpert 미리보기 호출
    $c.rpt.fn_open_report(testDateSet, rex_rptname, userParam);
};
